//! The argument rules of the attributes clang knows (spec/parse.md §6.2
//! "Argument table", WP-1879): how many arguments each takes and how its
//! argument clause is parsed, per spelling (`__attribute__`, `gnu::`,
//! `clang::`), clang release (19, 22) and target (aarch64, x86-64).
//!
//! The rows are generated by `scripts/gen-attr-args.py`, which probes
//! clang++-19 and clang++-22 (`attr_args_table.rs`; the readable form is
//! `docs/status/attr-args.tsv`). The parser uses them for an attribute
//! whose arguments kiln does not otherwise interpret: it parses the
//! clause as clang's `ParseAttributeArgsCommon` does and then checks the
//! count as clang's `handleCommonAttributeFeatures`.

use crate::Sema;
use kiln_ast::attr::AttrSyntax;
use kiln_diag::DiagId;
use kiln_source::Loc;
use kiln_source::symbol::Symbol;

#[path = "attr_args_table.rs"]
mod table;

/// No upper bound on the argument count.
const UNBOUNDED: u8 = u8::MAX;

/// A leading identifier is an identifier argument (clang
/// `attributeHasIdentifierArg`).
const F_IDENT: u16 = 1;
/// clang parses the clause with a parser of its own (`availability`,
/// `type_tag_for_datatype`, ...); kiln skips it.
const F_CUSTOM: u16 = 2;
/// Parsed late (thread-safety attributes after the class); kiln skips it.
const F_LATE: u16 = 4;
/// An argument may be a pack expansion (`attributeAcceptsExprPack`).
const F_PACK: u16 = 8;
/// The positions that must be string literals, a mask from this bit.
const F_STRINGS_SHIFT: u16 = 4;

/// One generated row: attribute `name` (its `__` affixes removed) takes
/// `min..=max` arguments under the configurations of `mask` (bit
/// `spelling * 4 + config`; spellings `__attribute__`, `gnu::`,
/// `clang::`; configs aarch64 at clang 19, at 22, x86-64 at 19, at 22).
#[derive(Clone, Copy, Debug)]
pub(crate) struct Row {
    name: &'static str,
    mask: u16,
    min: u8,
    max: u8,
    flags: u16,
}

/// A [`Row`].
const fn r(name: &'static str, mask: u16, min: u8, max: u8, flags: u16) -> Row {
    Row { name, mask, min, max, flags }
}

/// How the argument clause of one attribute spelling is parsed and
/// counted, for [`Sema::attr_arg_rule`].
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct AttrArgRule {
    /// The fewest arguments.
    pub min: u8,
    /// The most arguments, `None` for no bound.
    pub max: Option<u8>,
    /// A leading identifier is an identifier argument.
    pub ident: bool,
    /// An argument may be a pack expansion.
    pub pack: bool,
    strings: u16,
}

impl AttrArgRule {
    /// Whether argument `i` (counted as clang 19 counts it: from the first
    /// after a leading identifier) must be a string literal.
    #[must_use]
    pub fn string_at(&self, i: usize) -> bool {
        i < 16 && self.strings & (1 << i) != 0
    }
}

/// The row of `name` for spelling index `spelling` (0 `__attribute__`,
/// 1 `gnu::`, 2 `clang::`) under clang `compat` on x86-64 (`x86`) or
/// aarch64; `None` when clang does not know that spelling there.
fn row(name: &str, spelling: u16, compat: u32, x86: bool) -> Option<&'static Row> {
    let config = u16::from(compat >= 22) + 2 * u16::from(x86);
    let bit = 1u16 << (spelling * 4 + config);
    let rows = table::ROWS;
    let start = rows.partition_point(|r| r.name < name);
    rows[start..].iter().take_while(|r| r.name == name).find(|r| r.mask & bit != 0)
}

/// The rule of `name` (its `__` affixes removed) for spelling index
/// `spelling`, or `None` when there is none or its clause is not parsed
/// in clang's common form ([`F_CUSTOM`], [`F_LATE`]).
fn rule(name: &str, spelling: u16, compat: u32, x86: bool) -> Option<AttrArgRule> {
    let row = row(name, spelling, compat, x86)?;
    if row.flags & (F_CUSTOM | F_LATE) != 0 {
        return None;
    }
    Some(AttrArgRule {
        min: row.min,
        max: (row.max != UNBOUNDED).then_some(row.max),
        ident: row.flags & F_IDENT != 0,
        pack: row.flags & F_PACK != 0,
        strings: row.flags >> F_STRINGS_SHIFT,
    })
}

/// Every row of the table as (name, configuration mask), for
/// cross-checks: mask bit `spelling * 4 + config` (spellings
/// `__attribute__`, `gnu::`, `clang::`; configs aarch64 at clang 19, at
/// 22, x86-64 at 19, at 22).
pub fn table_rows() -> impl Iterator<Item = (&'static str, u16)> {
    table::ROWS.iter().map(|r| (r.name, r.mask))
}

/// The rule of `name` (normalized) for spelling `spelling` (`G`, `GS` or
/// `CL` of [`crate::attr_triage`]) under `compat` and `x86`, as
/// [`Sema::attr_arg_rule`] finds it.
#[must_use]
pub fn table_rule(name: &str, spelling: u8, compat: u32, x86: bool) -> Option<AttrArgRule> {
    rule(name, spelling_index(spelling)?, compat, x86)
}

fn spelling_index(spelling: u8) -> Option<u16> {
    match spelling {
        crate::attr_triage::G => Some(0),
        crate::attr_triage::GS => Some(1),
        crate::attr_triage::CL => Some(2),
        _ => None,
    }
}

impl Sema<'_, '_> {
    /// The argument rule of attribute `scope::name` written with `syntax`
    /// under this unit's clang release and target (spec/parse.md §6.2
    /// "Argument table"), when its clause is parsed in clang's common form.
    pub fn attr_arg_rule(
        &self,
        syntax: AttrSyntax,
        scope: Option<Symbol>,
        name: Symbol,
    ) -> Option<AttrArgRule> {
        let scope = scope.map(|s| crate::decl::norm_attr_scope(self.ast.symbols().as_str(s)));
        let spelling = spelling_index(crate::attr_triage::spelling_of(syntax, scope))?;
        let n = kiln_ast::attr::normalize_attr_name(self.ast.symbols().as_str(name));
        let x86 = self.abi.triple.arch == kiln_abi::target::Arch::X86_64;
        rule(n, spelling, self.clang_compat, x86)
    }

    /// Checks that `count` arguments suit `rule` (clang
    /// `handleCommonAttributeFeatures`): otherwise reports clang's error
    /// at the attribute's `loc` and returns false, and the attribute is
    /// dropped.
    pub fn check_attr_arg_count(
        &mut self,
        syntax: AttrSyntax,
        scope: Option<Symbol>,
        name: Symbol,
        rule: AttrArgRule,
        count: usize,
        loc: Loc,
    ) -> bool {
        let min = usize::from(rule.min);
        let max = rule.max.map(usize::from);
        let shown = self.attr_shown_parts(syntax, scope, name);
        let quoted = format!("'{shown}'");
        let d = if max == Some(min) {
            if count == min {
                return true;
            }
            if min <= 1 {
                self.diag(DiagId::parse_attribute_wrong_arg_count, loc)
                    .arg(shown)
                    .arg(min.to_string())
            } else {
                self.diag(DiagId::sema_attribute_wrong_number_arguments, loc)
                    .arg(quoted.clone())
                    .arg(min.to_string())
            }
        } else if count < min {
            if min == 1 {
                self.diag(DiagId::sema_attribute_too_few_arguments_one, loc).arg(quoted.clone())
            } else {
                self.diag(DiagId::sema_attribute_too_few_arguments, loc)
                    .arg(quoted.clone())
                    .arg(min.to_string())
            }
        } else if let Some(max) = max
            && count > max
        {
            if max == 1 {
                self.diag(DiagId::sema_attribute_too_many_arguments_one, loc).arg(quoted.clone())
            } else {
                self.diag(DiagId::sema_attribute_too_many_arguments, loc)
                    .arg(quoted.clone())
                    .arg(max.to_string())
            }
        } else {
            return true;
        };
        // clang reports it when it processes the attribute (WP-1854).
        self.emit_attr_diag(d, loc, quoted);
        false
    }
}
